// Shared modular geometry: the same parts become visible meshes and colliders.
export function buildingLayout(x,z,w,d,height,terrain){const y=Math.max(terrain(x-w/2,z-d/2),terrain(x+w/2,z-d/2),terrain(x-w/2,z+d/2),terrain(x+w/2,z+d/2)),floors=Math.max(1,Math.floor(height/3.6)),parts=[],chests=[];const add=(ox,oy,oz,sx,sy,sz,kind='wall')=>parts.push({position:[x+ox,y+oy,z+oz],size:[sx,sy,sz],kind});const h=floors*3.6;
add(0,-.12,0,w,.24,d,'floor');add(-w/2,h/2,0,.22,h,d);add(w/2,h/2,0,.22,h,d);add(0,h/2,-d/2,w,h,.22);const side=(w-2.4)/2;add(-(w+2.4)/4,h/2,d/2,side,h,.22);add((w+2.4)/4,h/2,d/2,side,h,.22);add(0,2.95,d/2,2.4,.9,.22);if(h>3.6)add(0,(h+3.6)/2,d/2,2.4,h-3.6,.22);add(0,h+.12,0,w+.4,.24,d+.4,'roof');
for(let floor=0;floor<floors;floor++){const level=floor*3.6;chests.push({x:x-w/2+2,y:y+level,z:z-d/2+2});if(floor){add(-1.2,level-.12,0,w-2.4,.24,d,'floor');add(w/2-1.2,level-.12,-d/2+1,2.4,.24,2,'floor');add(w/2-1.2,level-.12,d/2-1,2.4,.24,2,'floor');}if(floor<floors-1){const run=d-4,steps=Math.ceil(3.6/.3);for(let k=0;k<steps;k++)add(w/2-1.2,level+(k+1)*3.6/steps-.11,d/2-2-(k+.5)*run/steps,2.15,.22,run/steps+.015,'stairs');}if(w>12){add(-w*.18,level+1.3,-d*.2,.16,2.6,d*.42,'partition');add(-w*.18,level+1.3,d*.33,.16,2.6,d*.17,'partition');}}
// Broad low steps reach the entrance on sloping ground.
const outside=terrain(x,z+d/2+2),rise=Math.max(0,y-outside),count=Math.max(1,Math.ceil(rise/.25));for(let k=0;k<count;k++){const top=outside+rise*(k+1)/count;parts.push({position:[x,top-.12,z+d/2+(count-k)*.38],size:[2.5,.24,.42],kind:'stairs'});}return {y,floors,parts,chests};}
export function roadRibbon(a,b,width,height){const distance=Math.hypot(b[0]-a[0],b[1]-a[1]),segments=Math.ceil(distance/2),dx=b[0]-a[0],dz=b[1]-a[1],nx=-dz/(distance||1),nz=dx/(distance||1),bend=Math.min(18,distance*.09),points=[];for(let k=0;k<=segments;k++){const t=k/segments,offset=Math.sin(t*Math.PI)*bend,x=a[0]+dx*t+nx*offset,z=a[1]+dz*t+nz*offset,tx=dx+nx*bend*Math.PI*Math.cos(t*Math.PI),tz=dz+nz*bend*Math.PI*Math.cos(t*Math.PI),len=Math.hypot(tx,tz),sx=-tz/len,sz=tx/len;points.push({left:[x+sx*width/2,height(x+sx*width/2,z+sz*width/2)+.045,z+sz*width/2],right:[x-sx*width/2,height(x-sx*width/2,z-sz*width/2)+.045,z-sz*width/2],center:[x,height(x,z)+.065,z]});}return points;}
